mapper.select:

where member_id = #{owner} and merchant_id = #{merchant} and scope_type = 1
  and del_flag = 0 and status = 1
  and start_time is not null and end_time is not null
  and start_time < end_time and end_time > #{now}
  and name is not null and trim(name) != '' and description is not null and trim(description) != ''
  and (receive_count is null or receive_count >= 0)
  and (publish_count is null or publish_count <= 0 or ifnull(receive_count, 0) < publish_count)
  and id > #{cursor}
order by id asc limit #{limit}
